#define CLIP_CLIMB_DOWN_FRAMES 8
#define CLIP_CLIMB_UP_START 9
#define CLIP_CLIMB_UP_FRAMES 20
#define CLIP_JUMP_START 29
#define CLIP_JUMP_FRAMES 7
#define CLIP_LAND_START 36
#define CLIP_LAND_FRAMES 1
#define CLIP_PICKUP_START 37
#define CLIP_PICKUP_FRAMES 1
#define CLIP_RUN_START 38
#define CLIP_RUN_FRAMES 10
#define CLIP_SPLAT_START 48
#define CLIP_SPLAT_FRAMES 2
#define CLIP_TRANSITION_START 50
#define CLIP_TRANSITION_FRAMES 8

#endif

/* Every sound effect the game can play: SFX_CLIP(name, start frame, frame count).
   Only expanded by a file that has defined SFX_CLIP first. */
