SFX_CLIP(SFX_JUMP, CLIP_JUMP_START, CLIP_JUMP_FRAMES);
SFX_CLIP(SFX_LAND, CLIP_LAND_START, CLIP_LAND_FRAMES);
SFX_CLIP(SFX_PICKUP, CLIP_PICKUP_START, CLIP_PICKUP_FRAMES);
SFX_CLIP(SFX_RUN, CLIP_RUN_START, CLIP_RUN_FRAMES);
SFX_CLIP(SFX_SPLAT, CLIP_SPLAT_START, CLIP_SPLAT_FRAMES);
SFX_CLIP(SFX_TRANSITION, CLIP_TRANSITION_START, CLIP_TRANSITION_FRAMES);
#endif

